class Solution {
public:
    vector<int> sortItems(int n, int m, vector<int>& group, vector<vector<int>>& beforeItems) {
        for (int i = 0; i < n; i++) {
            if (group[i] == -1) group[i] = m++;
        }

        vector<vector<int>> itemAdj(n);
        vector<int> itemIndeg(n, 0);
        vector<vector<int>> groupAdj(m);
        vector<int> groupIndeg(m, 0);
        vector<vector<int>> itemsInGroup(m);
        vector<unordered_set<int>> groupEdgeSet(m);

        for (int i = 0; i < n; i++) {
            itemsInGroup[group[i]].push_back(i);
        }

        for (int i = 0; i < n; i++) {
            for (int before : beforeItems[i]) {
                if (group[before] == group[i]) {
                    itemAdj[before].push_back(i);
                    itemIndeg[i]++;
                } else {
                    if (groupEdgeSet[group[before]].insert(group[i]).second) {
                        groupAdj[group[before]].push_back(group[i]);
                        groupIndeg[group[i]]++;
                    }
                }
            }
        }

        queue<int> gq;
        for (int g = 0; g < m; g++) {
            if (groupIndeg[g] == 0) gq.push(g);
        }
        vector<int> groupOrder;
        while (!gq.empty()) {
            int g = gq.front(); gq.pop();
            groupOrder.push_back(g);
            for (int next : groupAdj[g]) {
                if (--groupIndeg[next] == 0) gq.push(next);
            }
        }
        if ((int)groupOrder.size() != m) return {};

        vector<int> result;
        for (int g : groupOrder) {
            queue<int> iq;
            for (int item : itemsInGroup[g]) {
                if (itemIndeg[item] == 0) iq.push(item);
            }
            int count = 0;
            while (!iq.empty()) {
                int item = iq.front(); iq.pop();
                result.push_back(item);
                count++;
                for (int next : itemAdj[item]) {
                    if (--itemIndeg[next] == 0) iq.push(next);
                }
            }
            if (count != (int)itemsInGroup[g].size()) return {};
        }

        return result;
    }
};
